 event('supp-cn148','china',148,'安世高在洛阳的译经活动','洛阳','安世高、汉语协作者','文本与科技','早期佛教文本进入汉语环境，需要语言协作、口述和读者理解。官修史书之外，僧传保存了另一类人员活动记忆。','安世高约于148年前后来到洛阳译经，相关传统涉及禅法及教义文本。翻译并非不经中介便把一部原作机械改写成汉字。','可与二世纪基督徒的翻译和释经比较组织条件，但不可把两种社群的文本、信仰和传播路线混为一条。','148年据僧传的汉桓帝初年来华记述作约年定位。译经署名、真伪及现存文本形成仍需目录学研究。',[gaoseng])
 event('supp-cn401','china',401,'鸠摩罗什进入长安与集体译场','长安','鸠摩罗什、姚兴、译场参与者','文本与科技','战争与政权竞争影响跨区域僧侣的行动。佛教经典解释同时依赖语言、学术与政治支持。','鸠摩罗什进入后秦长安，获得姚兴支持，随后组织翻译与讲论。弟子和汉语协作者参与文本形成与传播。','长安的译场揭示集体知识劳动。与后来景教译述或晚明合作比较时，应先区分经典语言、工作方式和赞助制度。','401年为到长安的节点，不是所有译作的完成年；“后秦”也不是秦始皇的秦，政权名称需带时代辨认。',[gaoseng])
 event('supp-cn439','china',439,'北魏灭北凉与北方整合','平城、姑臧','北魏太武帝、北凉统治者与居民','政治与制度','北魏建立后继续面对北方多政权并存的局势，战争与人口、工匠及知识的移动相互关联。','北魏攻灭北凉，常被作为北方统一的关键节点。南方刘宋仍存在，不能将北方整合写成全国统一。','政治整合为宗教和艺术赞助提供新条件，也带来征服与迁移代价。地图上颜色变化不能单独说明居民的全部经历。','439年与386年建魏、494年迁都洛阳分属不同阶段；具体地方控制与边疆关系仍须逐地判断。',[source('《魏书》世祖纪',W+'魏書/卷4下','太延五年北凉战事','古代史书'),timeline])
 event('supp-cn446','china',446,'北魏太武帝禁佛与政策执行','长安、平城及北方','北魏太武帝、崔浩、僧侣与地方官','宗教与思想','皇权、军事和宗教资源之间存在复杂关系，朝廷对僧团和寺院的评价也会随政治环境变化。','太武帝推动大规模禁佛，寺院、经典及僧侣的处境受到冲击；不同地方的执行与保存情况并不完全一致。','可与罗马迫害或会昌政策比较命令、财产与地方执行，而非只比较哪位君主更宽容。宗教群体往往拥有跨政策延续的实践。','446年为重要节点；北魏后来复法是另一政治阶段。不能从诏令一项文字推出所有北方佛教活动立即消失。',[wei])
 event('supp-cn460','china',460,'云冈石窟与北魏佛教赞助','平城、今大同','昙曜、北魏皇室、工匠与施主','宗教与思想','复法后的北魏借佛教造像表达宗教与政治秩序。洞窟制作还依赖工匠、材料、交通及长期供给。','云冈早期石窟约从460年展开，昙曜五窟成为重要部分。后续雕凿跨越多个阶段，并非一年内全部完成。','与拉文纳镶嵌画或教堂建筑并读，可以观察赞助人、理想形象与劳动组织；相似的宏伟尺度不等于相同的神学。','460年标工程的早期节点；不同洞窟年代、修补和风化情况有别，今天可见形态不是未经变化的五世纪现场。',[source('UNESCO：云冈石窟评估','https://whc.unesco.org/document/1118','460年起的雕凿及昙曜五窟','遗产实物与评估文献'),wei],end=525)
 event('supp-cn534','china',534,'北魏分裂与东西魏形成','洛阳、邺、长安','高欢、宇文泰、北魏宗室','政治与制度','北魏晚期的军镇、宫廷和地方冲突削弱中央统治。北方军事集团争夺皇帝与政治中心。','北魏分裂为东西两个统治系统：东魏于534年形成，西魏于535年建立。两者随后各有继承政权。','这补充从北魏直接跳到隋所遗漏的政治层次。战争和中心转移也影响寺院、工匠及经典活动。','534—535年是跨年分裂过程；不能写成两个政权在完全同一日建立，也不能因同用魏号便忽略实际权力差异。',[source('《魏书》出帝、孝静帝纪',W+'魏書/卷12','北魏末与东魏建制','古代官修史书'),timeline],end=535)
 event('supp-cn574','china',574,'北周宗教政策与儒释道的制度位置','长安及北周辖地','周武帝、佛道人员与官僚','宗教与思想','北周朝廷试图整合政治、财政及礼仪秩序，不同思想传统与皇权的关系成为公共问题。','周武帝时期废佛道的政策冲击寺观和宗教身份，其后战争扩展又把措施带入新的地区。','可与北魏和会昌比较国家如何处理宗教人员、土地和仪式，但各次政策的适用范围、理念和执行不能混为一谈。','574年突出政策节点；后来的复法与隋代赞助另有时间，不能据一次禁令认定相关传统永久终止。',[source('《周书》武帝纪',W+'周書/卷05','建德三年，宗教政策','古代史书')])
 event('supp-cn690','china',690,'武则天建立周与宗教政治表达','洛阳、长安','武则天、官僚与宗教人员','政治与制度','唐高宗以后，宫廷、官僚与宗室关系持续重组。女性统治者的权力需要借不同政治与宗教语言表达。','武则天称帝，改国号周，以洛阳为重要中心。佛教等资源参与合法性表达，但朝廷并非只依一种信仰治理。','与基督徒女统治者或女性修院领袖比较时，应区分皇权、财产、教育和宗教职分；不能用性别相同替代具体制度分析。','690年为建周节点，705年复唐另属后续事件；“武周”不是先秦周朝，也不是所有唐代制度在690年同时消失。',[source('《旧唐书》则天皇后纪',W+'舊唐書/卷6','载初、天授及改国号周','古代史书')])
 event('supp-cn916','china',916,'契丹称帝与辽的政治形成','契丹上京及北方','耶律阿保机、契丹与各地居民','政治与制度','唐末五代时期的北方不只有中原政权，契丹的组织、农牧资源与多种居民关系也在变化。','耶律阿保机称帝，契丹政权进入新的王朝建制阶段。后来的国号更改及南北面官等制度又有自己的形成过程。','这一节点补充宋之前的北方政治。辽宋关系须以并立政权而非单向的“宋朝边疆地方”来理解。','916年突出称帝，947年改国号大辽需另行辨认；不把后来的全部疆域提前放进初建政权。',[source('《辽史》太祖纪',W+'遼史/卷001','神册元年与契丹称帝','古代史书'),timeline])
 event('supp-cn932','china',932,'五代官刻经典工程的开端','洛阳、开封及刻书网络','冯道、官员与刻工','文本与科技','雕版技术已有长期实践，官府刻书把校定经典、教育与政治秩序联系起来。工程需要底本、校勘和工匠分工。','后唐朝廷批准刊刻儒家经典的工程，后经多个政权延续，到十世纪中叶逐步完成。','这让五代不只有战争和政权更替，也有跨朝代延续的知识劳动。与修院抄书比较时，可观察谁出资、如何校订及服务何种读者。','932年标工程获准开端，完成常系953年；不能说932年首次发明雕版印刷，或所有官版经典当年即印成。',[source('《旧五代史》冯道传',W+'舊五代史/卷126','奏请雕印经典及历朝事业','古代史书')],end=953)
 event('supp-cn1023','china',1023,'交子务与官府纸币制度','益州、四川','商人、宋朝官员与持券者','文本与科技','四川的贸易与货币条件促进可转让票据发展。纸、印刷、信用、兑付和监管必须共同运作，纸张本身不能产生信用。','官府在1023—1024年前后接管和组织交子发行，形成有范围和期限安排的纸币制度。','可以把印刷、文书与商业网络一起阅读，也与教会文本复制区别：同为印刷品，不代表它们有相同权威来源与使用方式。','这里选择制度转折的约年范围；不能把官交子的建立称为纸币此前完全不存在，亦不能把四川使用扩大成全国立即统一使用。',[money,source('《宋史》仁宗纪',W+'宋史/卷009','天圣元年，置益州交子务','古代史书')],end=1024)
 event('supp-cn1038','china',1038,'李元昊称帝与西夏建制','兴庆、宋夏边境','李元昊、党项及各族居民','政治与制度','西北已有长期的地方统治与族群联系，政治力量的形成早于正式称帝。农业、牧业、商道和宗教资源共同参与。','李元昊称帝，西夏进入新的国号和制度阶段；随后宋夏战争、议和及贸易持续发展。','宋、辽、夏并立需要同时呈现。文字、佛教与政治制度的相互借鉴，并不意味着一个政权只是另一个的被动复制。','1038年为称帝节点，不是当地历史的起点。1040年前后的战争和1044年议和另有时间。',[source('《宋史》夏国传',W+'宋史/卷485','李元昊及宝元元年','古代史书'),timeline])
 # Short biographies focus on named actors and the documents through which we know them.
 def profile(id,side,name,life,span,role,body,work,caution,sources,eventIds=None):
  data['people'].append(dict(id=id,side=side,name=name,lifeLabel=life,activeRange=span,role=role,sections=[dict(title='人物与处境',text=body),dict(title='贡献与关系',text=work),dict(title='史料与阅读提示',text=caution)],sources=sources,eventIds=eventIds or []))
 profile('perpetua','west','佩尔佩图阿与费利西塔','三世纪初；203年殉道',[203,203],'北非女性信徒；监狱与殉道叙述中的人物','她们处在不同社会身份和家庭关系中，共同进入北非的殉道记忆。叙事包含亲属、婴儿、同伴与执行权力，不只是一个抽象的受难故事。','《佩尔佩图阿与费利西塔受难记》让女性声音、梦境与群体记忆进入早期教会史。文本中自述、他人记录和编者组织需要分别辨认。','不能把现存文本全部当作两人共同留下的未经编辑日记，也不据某些叙事细节推断所有北非女性拥有同一生活。',[primary('church-015')],['church-015'])
 profile('macrina','west','小马克里娜','约327—379',[379,379],'卡帕多西亚的修道生活参与者','马克里娜与巴西尔、尼撒的贵格利等家族成员相关，家庭财产、教育与禁欲生活相互交织。她并不只是著名男性神学家的背景人物。','贵格利的传记和对话把她呈现为教师与精神权威，提供观察家庭如何转为共同生活网络的材料。相关言论也经过作者的文学组织。','现存形象主要由其弟书写；圣徒传及哲学对话不能等同于独立采访，缺少更多声音之处应保持开放。',[source('尼撒的贵格利《马克里娜传》',B+'basis/macrina.asp','家族、共同生活及临终叙述','古代圣徒传旧英译')])
 profile('hilda','west','惠特比的希尔达','614—680',[657,680],'修院领袖；教育与教会交往参与者','希尔达领导的共同生活和教育环境联系王室、僧侣与不同教会传统。惠特比讨论的地点并不是没有人物活动的会议厅。','比德记述她对教导、诗歌传统和群体治理的影响；她的修院也为理解早期中世纪女性权威提供重要线索。','有关她的叙述来自后来教会史，赞誉、神迹及具体制度需要分别阅读，不能由一所修院推断所有女性都拥有相同权力。',[bede,source('比德《教会史》第四卷',B+'basis/bede-book4.asp','第23章，希尔达与修院','古代文献旧英译')])
 profile('bede','west','比德','约672/673—735',[731,735],'修士；教会史、圣经注释与纪年作者','比德生活于英格兰北方修院环境，书籍、教师与通信支持其研究。他的著述不只包括一部民族教会史。','《英吉利教会史》把地方资料组织为信仰与群体形成的叙事，也影响后来人如何理解不同王国的过去。','作者的取舍会突出某些人物并遮蔽另一些人。成书年、抄本年与所叙事件年应分开，不能拿精美抄本作七世纪现场图。',[bede5])
 profile('timothy','west','提摩太一世','约八世纪前期—823',[780,823],'东方教会宗主教；书信和对话传统人物','他长期任职于阿拔斯政治环境下，面对远距离教会联系、学术传统与宫廷关系。东方教会的活动并不能全用拉丁欧洲概念解释。','传世宗教对话呈现基督徒如何以经文、理性和比喻回应穆斯林提问；书信又联系组织和地方处境，构成不同类型的材料。','宫廷对话经过成文与传抄，不代表两个宗教全部信众的意见；现存社群分布也不能仅据称号推算。',[tim])
 profile('hildegard','west','宾根的希尔德加德','1098—1179',[1141,1179],'修院领袖；异象、音乐与书信作者','她的活动连接修院治理、宗教表达和跨区域通信，写作和传阅也依赖秘书、抄写者与支持者。','《知路》、书信和音乐展示女性如何进入教会公共讨论。不同作品的主题、体裁和编纂条件不尽相同，不宜只用神秘主义者一个词概括。','异象的宗教意义与其现代生理诊断不是同一问题；不在缺乏证据时替历史人物下医学结论，也不把后世抄本全当本人亲笔。',[primary('world-028')],['world-028'])
 profile('clare','west','阿西西的克拉拉','约1193/1194—1253',[1212,1253],'女性修道群体领袖；会规作者','克拉拉与方济各运动相联系，但女性共同生活面临自身的财产、空间与教会认可问题，不能仅作男性托钵修士的附属。','她领导圣达弥盎群体，并在会规与书信中表达贫穷和共同生活的选择。1253年获认可的会规是重要文本。','1212年早期选择与1253年会规批准分属不同阶段；后来的修会制度及圣徒图像也不能全部提前套入她在世时。',[source('梵蒂冈：阿西西的克拉拉','https://www.vatican.va/content/benedict-xvi/en/audiences/2010/documents/hf_ben-xvi_aud_20100915.html','生平、书信与会规','当代教会历史解说'),primary('world-031')],['world-031'])
 profile('teresa','west','阿维拉的德肋撒','1515—1582',[1562,1582],'加尔默罗改革者；宗教著述作者','德肋撒在西班牙修院与宗教审查环境中组织改革，需要处理筹资、地方支持、教会许可和内部争议。','她的自传、祈祷著述及建院记录，把个人经验与组织行动联系起来，为理解天主教更新提供女性视角。','不能把她的经验脱离具体作品和审查处境，也不将新教改革、天主教更新和各地方实行简单视为同一条路线。',[primary('world-064')],['world-064'])
 profile('alopen','china','阿罗本','七世纪；具体生卒年不详',[635,638],'景教碑所记来华宗教人员','阿罗本的活动主要通过781年景教碑对贞观时期的回顾为人所知。其出发地点和完整生平并不能由一个名称重建。','碑文把携经来华、翻译、朝廷接待与建寺许可连为一段群体起源叙事，帮助定位唐代基督徒公共记忆。','635、638与781年分别属于来华记述、许可记述和立碑；不能将立碑者的赞语当作当事人的现场日记。',[primary('world-010'),primary('world-077')],['world-010','world-077'])
 profile('sauma','china','拉班扫马','约十三世纪前期—1294',[1287,1294],'出身东方基督徒环境的旅行者与外交使者','他从东方西行，在西亚政治与教会环境中承担外交任务。其故事能打破所有传播都由欧洲向东方单向进行的印象。','欧洲使行涉及不同统治者、教会礼仪与翻译。外交与宗教身份相互关联，但不表示各方已经建立一个统一政治或教会组织。','传世旅行叙述经过编写，具体出发年代、族属称谓与现代民族身份不可简单等同；1287年主要标欧洲使行。',[primary('world-035')],['world-035'])
 profile('lizhizao','china','李之藻','1565—1630',[1602,1630],'明代士人；刊印、译写与宗教交流参与者','李之藻通过自己的学术与政治网络参与晚明中西交往。文本的传播依赖刊印、筹资、校订和向读者作出解释。','其与地图、数学及宗教文献的关系，说明合作不只发生在徐光启与利玛窦两人之间。《天学初函》等编刊又有不同时间和内容。','不能把一件地图的作者署名自动当作所有工作的个人独创，也不将受洗等同于他对所有欧洲观点毫无选择地接受。',[primary('world-083')],['world-083'])
 profile('yangtingyun','china','杨廷筠','1562—1627',[1611,1627],'晚明士人；中国基督徒著述与支持网络参与者','杨廷筠在杭州等地的士人、家族与宗教关系中理解新信仰，其选择和辩护具有中国读者自身的问题意识。','他参与撰写、支持和解释基督宗教文本，与其他中国信徒及传教人员合作，构成不同于单纯宫廷许可的地方网络。','1611为常见归信年份；个人立场和后来信徒群体的全部经验不能互相代替，也不把“教会三柱石”的后设称呼当成正式统一职分。',[primary('world-085')],['world-085'])
 sites=[]
 def site(id,title,placeIds,role,geography,network,reading,personIds):
  ids=placeIds.split(',');events=[e for e in atlas['events'] if e.get('module')!='ot' and e['place'] in ids]
  sites.append(dict(id=id,title=title,placeIds=ids,role=role,range=[min(e['year'] for e in events),max(e['year'] for e in events)],sections=[dict(title='地理与城市环境',text=geography),dict(title='人员与文本网络',text=network),dict(title='怎样读这座城市',text=reading)],eventIds=[e['id'] for e in events],personIds=personIds.split(','),sources=[primary(e['id']) for e in events[:2]]))
 site('site-jerusalem','耶路撒冷','jerusalem','经文群体、圣地与多次政治转折','耶路撒冷位于犹太山地，其圣地、居民及周边道路把城市与不同地方连接。古代政区、现代城市范围和地图代表点需要分开。','使徒行传的耶路撒冷群体、70年的战争、后来的圣地与十字军记忆属于不同时代。人员来往有礼仪、行政、朝圣和军事等多种目的。','不要把所有年代压成一幅永久不变的圣城图。每次浏览都需辨认实际统治者、文本作者和城市中的不同居民。','peter,paul')
 site('site-antioch','安提阿','antioch','差遣、跨语言交往与城市教会','这里指叙利亚安提阿，靠近奥龙特斯河与东地中海交通网络；不是彼西底安提阿。两座同名城市在使徒行传中承担不同角色。','安提阿群体、巴拿巴与保罗、伊格那丢及后来的神学争论连为多条线索。港口、家庭、主教和书信都参与联系，不能仅讲一次出发。','同一城市在不同世纪的社群与机构有变化。不能因后来出现某种释经传统，就把它全部倒推给一世纪的每个信徒。','paul,priscilla')
 site('site-alexandria','亚历山大里亚','alexandria','港口、经典研究与城市权力','埃及的亚历山大里亚连接地中海与尼罗河流域，是不同语言、教育与宗教群体交往的城市；它不代表整个埃及的共同经验。','俄利根、亚他那修及后来的主教争论体现经典研究和教会权威。城市中的犹太人、其他宗教实践和政治力量也参与历史。','所谓亚历山大传统不是从创始时就固定的一套思想。应区分学校、教导活动、主教机构及后世学派归类。','athanasius')
 site('site-syriac','埃德萨与尼西比斯','edessa,nisibis','叙利亚语、学校与边境迁移','两座城市位于上美索不达米亚的不同节点。罗马与萨珊边界变动影响居民、教师和文本，但文化联系并不总与国界重合。','以法莲的迁移、纳尔塞及学校传统帮助理解叙利亚语知识网络。译经、诗歌、教导与共同生活并不是一种完全相同的机构。','主图代表点不是学校遗址的精确门址；关于传承起源的叙述还需区分当时材料与后来的机构自我记忆。','timothy')
 site('site-constantinople','君士坦丁堡与邻近会议城市','constantinople,nicaea,chalcedon','帝国礼仪、会议与跨区域权威','君士坦丁堡连接博斯普鲁斯海峡两岸，尼西亚和迦克墩位于附近不同城市。会议名称并不表示它们在同一栋建筑举行。','皇帝、宗主教、修院与其他地区代表在此形成复杂关系。大公会议、圣像争论及奥尔加的宫廷访问体现不同的流动网络。','帝国中心的文献容易使地方经验隐形；应同时阅读不同教会对会议的接受，不能把一项朝廷命令直接当作所有居民的信仰。','constantine,justinian')
 site('site-changan','长安','xian','唐代多语言环境与景教碑','唐长安的城市格局、寺院和政治空间，与现代西安并不完全重合。地图点位表示城市区域，不保证每座寺院的精确位置已被确定。','阿罗本来华、翻译、建寺记述以及781年碑文，连接朝廷、汉语读者与东叙利亚语群体。僧人、官员和不同语言人员共同参与。','碑首图像、碑文、现代陈列地点与原立碑环境是不同对象。看到一件碑刻不能直接推算全国信徒数量或各地持续时间。','alopen,jingjing,taizong,xuanzang')
 site('site-beijing','大都、北京','beijing','元代跨洲教会与晚明翻译网络','元大都和明清北京在相近城市空间中经历不同规划和政治结构。用现代坐标定位并不表示各时代的宫廷与教堂处于完全同一位置。','孟高维诺的报告、利玛窦与中国合作者、历法工作都与这座城市有关，但相隔数百年，不构成一条无需证据的连续机构谱系。','阅读时先核对时代、人员和机构。宫廷许可不自动代表全国地方的处境，政治更替也不能说明每个社群在同一天消失。','ricci,xuguangqi,lizhizao')
 site('site-rome','罗马','rome','使徒记忆、城市教会与跨国行政','罗马的道路和港口联系地中海多地，古代帝国城市、教宗辖区与现代城市属于不同政治地理层次。','保罗叙事的结尾、使徒殉道记忆、主教书信和后来教廷行政分属不同文本。读者需要辨认一世纪人物与后世制度的发展距离。','不要因“罗马”一词相同，就把帝国、城市居民、罗马主教和所有拉丁基督徒视为同一行动者。','peter,paul,francis')
 site('site-wittenberg','维滕贝格与改革城市','wittenberg,worms,augsburg','大学、印刷与帝国政治','维滕贝格的大学与印刷网络，与沃尔姆斯议会、奥格斯堡的信纲和和约共同构成多个地点的改革历史，并非一座城市完成全部过程。','教师、印工、学生、城市居民与诸侯参与文本传播。论纲、信纲及政治协议有不同作者、读者与约束对象。','与晚明译书并读时，比较具体工作与制度条件，不只给两座城市各放一位伟人的画像。','luther,calvin')
 site('site-indianocean','马拉巴尔与果阿','kerala,goa','印度洋、多种基督徒传统及海上帝国','马拉巴尔沿岸与果阿是不同区域，既有印度洋航海和商人网络，又有葡萄牙海上权力扩展带来的新制度。','叙利亚语礼仪传统、地方基督徒、拉丁修会和殖民官员交往并发生冲突。沙勿略的来信不是印度所有基督徒历史的起点。','要区分地方社群自述、旅行见闻、会议决定与殖民行政。1599年会议及后来的接受不能当作毫无争议的自然合一。','timothy')
 data['places']=sites
 terms=[]
 def term(id,title,meaning,distinction,related):
  terms.append(dict(id=id,title=title,sections=[dict(title='基本含义',text=meaning),dict(title='容易混淆的地方',text=distinction)],eventIds=related,sources=[primary(related[0])]))
 term('canon','正典与书目','正典指一个信仰群体认可为具有规范权威的经书集合。实际形成涉及礼拜、抄写、引用、讨论与不同地方的书目见证。','某位作者列书单、某次会议作安排与所有地方立即统一不是同一件事。尼西亚会议不能被简单写成一次投票创造二十七卷新约。',['church-035'])
 term('council','大公会议与地方会议','会议是主教或其他代表共同讨论信仰、纪律和组织问题的方式。后来被称为大公的会议，其地位也与不同教会的接受有关。','会议名称、举行年份、定义文本及地方接受是不同层次；不能把今天某传统认可的会议列表当成当时所有基督徒一致使用的名单。',['church-029','church-046'])
 term('christology','基督论','基督论讨论耶稣基督的身份、神性与人性及相关表达。古代争论牵涉经文、救恩、礼仪与语言，而不是只有几个技术名词。','不同语言中“位格”“性”等词不总能逐字对应；用后世一句标签概括所有参与者，可能遮蔽他们实际强调的问题。',['church-045','church-046','world-012'])
 term('eastchurch','东方教会与东叙利亚传统','本项目用东方教会指在美索不达米亚、伊朗及更东方发展的一组历史社群与组织，东叙利亚语礼仪和学术传统是重要联系。','它不等于所有位于欧洲以东的教会，也不等同于现代东正教。唐代“景教”名称与现代宗派名称之间不能直接画等号。',['world-005','world-010'])
 term('nonchalcedon','非迦克墩传统','这里概括未接受迦克墩会议定义的一些历史传统；它们内部也有不同语言、地方组织和表达，今天有具体教会名称。','不能因其不接受某一定义，便断言他们否认基督人性；历史论争中的敌对标签，应与相关群体的自我表述分别呈现。',['church-046','world-008'])
 term('patriarch','主教、宗主教与教宗','主教承担地方教会的教导、礼仪和组织责任。某些重要中心逐渐形成更广联系，宗主教及罗马教宗的权威又有各自发展。','称号相似不表示每个时代拥有相同辖权；礼仪中的尊位、实际行政能力和现代国家边界也不是一回事。',['world-001','world-080'])
 term('icons','圣像、敬礼与崇拜','图像可进入教导、祈祷、纪念和公共礼仪。圣像争论涉及基督如何被描绘、图像与所指对象的关系，以及政治和修院资源。','支持圣像者对敬礼与仅归于上帝的崇拜有区分，翻译时术语可能产生误解；不能只把争论说成有人喜欢画、有人不喜欢画。',['world-013','world-015'])
 term('filioque','和子句','和子句指拉丁信经传统中关于圣灵发出关系的“及子”表述。争议牵涉神学含义、语言和谁有权更改共同信经。','它不是1054年突然发明的一句话，也不能单独解释全部东西教会关系。神学表达与教会权威问题需要关联而分别研究。',['world-022'])
 term('monastic','修道与托钵团体','修道生活包含不同形式的共同生活或独处、祈祷、劳动与纪律。托钵运动则与城市讲道、贫穷实践及新的组织方式相关。','本笃传统、埃及隐修、方济各团体和女性修院并不完全相同；同叫修道者，也不能推定财产、职分与生活规则一致。',['church-022','world-003','world-031'])
 term('scholastic','经院神学','经院神学在学校与大学环境中借助问题、论证、经文和权威著作开展讨论。它联系教学、注释与公开辩论，不只是一个抽象思想派别。','经院内部存在分歧，也不完全等于亚里士多德哲学。与宋代理学比较时，应说明不同经典、机构及论证规则，而不是直接说两者相同。',['world-034'])
 term('justification','称义与宗教改革','称义涉及罪人如何在上帝面前得蒙接纳，不同改革者与天主教传统对信、恩典、行为及圣礼有不同关系说明。','“因信称义”不能简化为行为和伦理完全无关；路德宗、改革宗及天主教的正式文本，也应结合各自语境和后来的对话阅读。',['world-048','world-054','world-065'])
 term('rites','中国礼仪之争','争论涉及对祭祖、祭孔及相关礼节的宗教和社会性质如何判断，也涉及翻译、地方实践、修会报告与教廷权威。','1645年决定只是长过程中的一环，不能把后来所有裁决和禁令提前到此年；国家采用历法与对礼仪的教会判断也不是同一事件。',['world-087'])
